DELETE FROM comments;
DELETE FROM blocks;
DELETE FROM database_rows;
DELETE FROM databases;
DELETE FROM pages;
DELETE FROM workspaces;
DELETE FROM users;
DELETE FROM counters;
UPDATE database_rows
SET properties_json = json_object(
      'date', json_extract(properties_json,'$.date'),
      'amount_minor', CASE CAST(substr(row_id,-4) AS INTEGER) % 12
        WHEN 0 THEN 119500 WHEN 1 THEN 38500 WHEN 2 THEN 52000 WHEN 3 THEN 18000
        WHEN 4 THEN 146000 WHEN 5 THEN 25000 WHEN 6 THEN 79000 WHEN 7 THEN 92500
        WHEN 8 THEN 133000 WHEN 9 THEN 42000 WHEN 10 THEN 27500 ELSE 64000 END
        + (CAST(substr(row_id,-2) AS INTEGER) % 9) * 137,
      'lane', CASE CAST(substr(row_id,-4) AS INTEGER) % 6 WHEN 0 THEN 'ordinary_cash' WHEN 1 THEN 'card_due' WHEN 2 THEN 'estimated_tax' WHEN 3 THEN 'estate_request' WHEN 4 THEN 'ira_estimate' ELSE 'reserve_review' END,
      'status', CASE CAST(substr(row_id,-4) AS INTEGER) % 4 WHEN 0 THEN 'paid' WHEN 1 THEN 'scheduled' WHEN 2 THEN 'pending_documents' ELSE 'reviewed' END,
      'counterparty', CASE CAST(substr(row_id,-4) AS INTEGER) % 8 WHEN 0 THEN 'Home Loan Servicing' WHEN 1 THEN 'Card Bank' WHEN 2 THEN 'US Treasury' WHEN 3 THEN 'Northstar Custody' WHEN 4 THEN 'Harbor Design Consulting' WHEN 5 THEN 'Memorial Travel Vendor' WHEN 6 THEN 'Health Plan' ELSE 'Household Transfer' END,
      'evidence', 'ledger date ' || json_extract(properties_json,'$.date') || '; source row ' || row_id
    );

UPDATE blocks
SET content_json = json_object('text', CASE position % 8
      WHEN 0 THEN 'Custodian file note: beneficiary registration and distribution election are separate documents; confirm acceptance before treating any amount as pending.'
      WHEN 1 THEN 'CPA file note: distinguish general beneficiary rules from account-specific facts and keep withholding estimates separate from actual tax due.'
      WHEN 2 THEN 'Liquidity file note: reconcile checking, bill-pay, both cards, and scheduled payments before considering an inherited-account distribution.'
      WHEN 3 THEN 'Reserve file note: the estate reserve remains restricted unless Leah records a later instruction after counsel review.'
      WHEN 4 THEN 'Card file note: statement balance, minimum due, APR, payment authorization, and payment status are different fields.'
      WHEN 5 THEN 'Estate reimbursement file note: receipt, executor authority, payee, amount, and payment status are required before payment.'
      WHEN 6 THEN 'Source file note: IRS Publication 590-B and estimated-tax dates provide general guidance; custodian correspondence supplies account processing facts.'
      ELSE 'Closeout file note: classify actions as completed, pending, deferred, or prohibited and link each conclusion to a backend object or source.'
    END || ' Archive position ' || position || '.');
